/**
* Inspector widget to aid in debugging voxels
*
* @alias VoxelInspector
* @constructor
*
* @param {Element|string} container The DOM element or ID that will contain the widget.
* @param {Scene} scene the Scene instance to use.
*/
function VoxelInspector(container, scene) {
	Check.defined("container", container);
	Check.typeOf.object("scene", scene);
	container = getElement(container);
	const element = document.createElement("div");
	const viewModel = new VoxelInspectorViewModel(scene);
	this._viewModel = viewModel;
	this._container = container;
	this._element = element;
	const text = document.createElement("div");
	text.textContent = "Voxel Inspector";
	text.className = "cesium-cesiumInspector-button";
	text.setAttribute("data-bind", "click: toggleInspector");
	element.appendChild(text);
	element.className = "cesium-cesiumInspector cesium-VoxelInspector";
	element.setAttribute("data-bind", "css: { \"cesium-cesiumInspector-visible\" : inspectorVisible, \"cesium-cesiumInspector-hidden\" : !inspectorVisible}");
	container.appendChild(element);
	const panel = document.createElement("div");
	panel.className = "cesium-cesiumInspector-dropDown";
	element.appendChild(panel);
	const { createSection, createCheckbox, createRangeInput, createButton } = InspectorShared;
	const displayPanelContents = createSection(panel, "Display", "displayVisible", "toggleDisplay");
	const transformPanelContents = createSection(panel, "Transform", "transformVisible", "toggleTransform");
	const clippingPanelContents = createSection(panel, "Clipping", "clippingVisible", "toggleClipping");
	const shaderPanelContents = createSection(panel, "Shader", "shaderVisible", "toggleShader");
	displayPanelContents.appendChild(createCheckbox("Depth Test", "depthTest"));
	displayPanelContents.appendChild(createCheckbox("Show", "show"));
	displayPanelContents.appendChild(createCheckbox("Disable Update", "disableUpdate"));
	displayPanelContents.appendChild(createCheckbox("Debug Draw", "debugDraw"));
	displayPanelContents.appendChild(createCheckbox("Jitter", "jitter"));
	displayPanelContents.appendChild(createCheckbox("Nearest Sampling", "nearestSampling"));
	displayPanelContents.appendChild(createRangeInput("Screen Space Error", "screenSpaceError", 0, 128));
	displayPanelContents.appendChild(createRangeInput("Step Size", "stepSize", 0, 2));
	const maxTrans = 10;
	const maxScale = 10;
	const maxAngle = CesiumMath.PI;
	transformPanelContents.appendChild(createRangeInput("Translation X", "translationX", -maxTrans, +maxTrans));
	transformPanelContents.appendChild(createRangeInput("Translation Y", "translationY", -maxTrans, +maxTrans));
	transformPanelContents.appendChild(createRangeInput("Translation Z", "translationZ", -maxTrans, +maxTrans));
	transformPanelContents.appendChild(createRangeInput("Scale X", "scaleX", 0, +maxScale));
	transformPanelContents.appendChild(createRangeInput("Scale Y", "scaleY", 0, +maxScale));
	transformPanelContents.appendChild(createRangeInput("Scale Z", "scaleZ", 0, +maxScale));
	transformPanelContents.appendChild(createRangeInput("Heading", "angleX", -maxAngle, +maxAngle));
	transformPanelContents.appendChild(createRangeInput("Pitch", "angleY", -maxAngle, +maxAngle));
	transformPanelContents.appendChild(createRangeInput("Roll", "angleZ", -maxAngle, +maxAngle));
	makeCoordinateRangeWithDynamicMinMax("Max X", "Min X", "Max Y", "Min Y", "Max Z", "Min Z", "clippingBoxMaxX", "clippingBoxMinX", "clippingBoxMaxY", "clippingBoxMinY", "clippingBoxMaxZ", "clippingBoxMinZ", "shapeIsBox", clippingPanelContents);
	makeCoordinateRangeWithDynamicMinMax("Max Longitude", "Min Longitude", "Max Latitude", "Min Latitude", "Max Height", "Min Height", "clippingEllipsoidMaxLongitude", "clippingEllipsoidMinLongitude", "clippingEllipsoidMaxLatitude", "clippingEllipsoidMinLatitude", "clippingEllipsoidMaxHeight", "clippingEllipsoidMinHeight", "shapeIsEllipsoid", clippingPanelContents);
	makeCoordinateRangeWithDynamicMinMax("Max Radius", "Min Radius", "Max Angle", "Min Angle", "Max Height", "Min Height", "clippingCylinderMaxRadius", "clippingCylinderMinRadius", "clippingCylinderMaxAngle", "clippingCylinderMinAngle", "clippingCylinderMaxHeight", "clippingCylinderMinHeight", "shapeIsCylinder", clippingPanelContents);
	const shaderPanelEditor = document.createElement("div");
	shaderPanelContents.appendChild(shaderPanelEditor);
	const shaderEditor = document.createElement("textarea");
	shaderEditor.setAttribute("data-bind", "textInput: shaderString, event: { keydown: shaderEditorKeyPress }");
	shaderPanelEditor.className = "cesium-cesiumInspector-styleEditor";
	shaderPanelEditor.appendChild(shaderEditor);
	const compileShaderButton = createButton("Compile (Ctrl+Enter)", "compileShader");
	shaderPanelEditor.appendChild(compileShaderButton);
	const compilationText = document.createElement("label");
	compilationText.style.display = "block";
	compilationText.setAttribute("data-bind", "text: shaderCompilationMessage, style: {color: shaderCompilationSuccess ? 'green' : 'red'}");
	shaderPanelEditor.appendChild(compilationText);
	knockout_default.applyBindings(viewModel, element);
}
